'use strict';
const assert=require('assert');
const fs=require('fs');
const path=require('path');
const root=path.resolve(__dirname,'..');
const app=fs.readFileSync(path.join(root,'app.js'),'utf8');
const html=fs.readFileSync(path.join(root,'index.html'),'utf8');
const mobile=fs.readFileSync(path.join(root,'mobile.html'),'utf8');
const css=fs.readFileSync(path.join(root,'styles.css'),'utf8');
const sw=fs.readFileSync(path.join(root,'service-worker.js'),'utf8');
const sql=fs.readFileSync(path.resolve(root,'..','migration-v56-0-0-master-hardening.sql'),'utf8');
function has(text,needle,message){assert(text.includes(needle),message);}
has(html,'56.0.5-schedule-card-format1','desktop assets must use the v56 token');
has(mobile,'56.0.5-schedule-card-format1','mobile assets must use the v56 token');
has(sw,'tuinbooks-shell-v56-0-5-schedule-card-format1','service worker cache must be current');
has(app,"const TUINBOOKS_VERSION_V5600='56.0.5-schedule-card-format1'",'master hardening module missing');
has(app,'complete_field_visit_v56','field completion must use the idempotent RPC');
has(app,'taskOutcomesV56','per-task outcomes must be preserved');
has(app,'completionLocationV56','completion location status must be preserved');
has(app,'unresolvedWorkItemsV56','Needs resolution must include missing work logs');
has(app,"row.queueSource!=='missed-unresolved'",'unresolved work must not enter Work to schedule before approval');
has(app,'openCustomerPaymentV56','combined customer payment allocation must exist');
has(app,'openMergeClientV56','duplicate-customer merge must exist');
has(app,'serviceSitesV56','multiple service sites must persist');
has(app,'revokeFieldDeviceV56','office device revocation must exist');
has(app,'reset_blocked','live-business reset attempts must be audited');
assert(!mobile.includes('mobileOpportunityUrgencyV551'),'field opportunity capture must not ask the worker for urgency');
assert(!mobile.includes('mobileOpportunityNextV551'),'field opportunity capture must not ask the worker for an office decision');
has(css,'v56.0.0 — master hardening','v56 UI styling missing');
has(sql,'tuinbooks_is_business_member_v56','membership RLS helper missing');
has(sql,'complete_field_visit_v56','field completion RPC migration missing');
has(sql,'field_submission_receipts_v56','field idempotency receipts missing');
has(sql,'field_device_status_v56','field-device status tracking missing');
has(sql,'Business data reset is disabled for live businesses','server-side reset gate missing');
console.log('v56.0.0 master hardening static tests passed');
